    @lru_cache(None)
    def f(used):
        i=next((z for z in range(n) if not (used>>z)&1),None)
        if i is None:return 0
        best=f(used|1<<i)
        for j in range(i+1,n):
            if not (used>>j)&1 and 2*b[i]<=b[j]:
